//! Spec node VIZ.CAPTURE.REC.POLICY: AC-1 .. AC-4 and the fail-closed rules.
//!
//! Expected values are independent of this crate: `fixtures/viz/capture/policy-matrix.csv` is
//! generated by `make_policy_matrix.py` (a Python reference of the leaf's rules, checked in CI),
//! and `fixtures/viz/capture/list-values-fresh.json` is hand-labelled from REQ-001. Every policy
//! here is read through the real settings resolver from real settings files, and changes go
//! through the real settings commands of fid-store.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_canon::{parse, to_canonical_bytes, CValue};
use fid_capture::rec::policy::{
    capture_settings, Decision, ForbidCause, MediaKind, Permission, Policy, Recording, RecordingPolicy, RetentionError,
    UtcInstant, POLICY_KEYS, RECORDING_KEY, RETENTION_DAYS_KEY, SCREENSHOTS_KEY, WINDOW_CAPTURE_KEY,
};
use fid_registry::Surface;
use fid_registry_build::{settings, workspace_catalogue, SettingsSource, SETTINGS_SOURCES};
use fid_store::settings::{
    list_to_value, list_values, resolve, set_admin_value, set_value, ActivityLog, Caller, ChangeEntry, FileStore,
    JournalTarget, ListValuesParams, PrincipalKind, Resolved, Scope, SetValueParams, SettingValue, SettingWarning,
    SettingsCtx, SettingsJournal, SettingsRegistry, Source, Sources, WarningReason,
};
use std::cell::RefCell;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, Ordering};

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/viz/capture");
const START: &str = "2026-11-17T10:00:00Z";

// ------------------------------------------------------------------ helpers

struct TempDir(PathBuf);

impl TempDir {
    fn new(tag: &str) -> TempDir {
        static N: AtomicU32 = AtomicU32::new(0);
        let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().subsec_nanos();
        let name = format!("fid-capture-{tag}-{}-{nanos}-{}", std::process::id(), N.fetch_add(1, Ordering::SeqCst));
        let p = std::env::temp_dir().join(name);
        std::fs::create_dir_all(&p).unwrap();
        TempDir(p)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// A fresh install: empty user and machine configuration directories, no project.
struct Install {
    _dir: TempDir,
    user: FileStore,
    machine: FileStore,
}

impl Install {
    fn new(tag: &str) -> Install {
        let dir = TempDir::new(tag);
        let user = FileStore::new(Scope::User, dir.0.join("user").join("settings.json")).unwrap();
        let machine = FileStore::new(Scope::Machine, dir.0.join("machine").join("settings.json")).unwrap();
        std::fs::create_dir_all(dir.0.join("user")).unwrap();
        std::fs::create_dir_all(dir.0.join("machine")).unwrap();
        Install { _dir: dir, user, machine }
    }

    fn sources(&self) -> Sources<'_> {
        Sources { project: None, user: &self.user, machine: &self.machine }
    }

    fn policy(&self) -> (RecordingPolicy, Vec<SettingWarning>) {
        RecordingPolicy::from_settings(&self.sources())
    }

    /// Writes a settings file by hand: `values` is the JSON text of the `values` member.
    fn write(&self, scope: Scope, values: &str) {
        let text = format!(r#"{{"format": "fid-settings/1", "values": {{{values}}}}}"#);
        self.write_raw(scope, text.as_bytes());
    }

    fn write_raw(&self, scope: Scope, bytes: &[u8]) {
        let path = if scope == Scope::User { self.user.path() } else { self.machine.path() };
        std::fs::write(path, bytes).unwrap();
    }

    fn machine_path(&self) -> &Path {
        self.machine.path()
    }
}

#[derive(Default)]
struct RecJournal(RefCell<Vec<(JournalTarget, ChangeEntry)>>);

impl SettingsJournal for RecJournal {
    fn commit(&self, target: &JournalTarget, entry: &ChangeEntry) -> Result<(), String> {
        self.0.borrow_mut().push((target.clone(), entry.clone()));
        Ok(())
    }
}

#[derive(Default)]
struct Log(RefCell<Vec<SettingWarning>>);

impl ActivityLog for Log {
    fn warn(&self, w: &SettingWarning) {
        self.0.borrow_mut().push(w.clone());
    }
}

const HUMAN_CLI: Caller = Caller { kind: PrincipalKind::Human, surface: Surface::Cli };
const AGENT_MCP: Caller = Caller { kind: PrincipalKind::Agent, surface: Surface::Mcp };

/// Every workspace setting plus this crate's, checked together against the merged catalogue.
fn workspace_registry() -> SettingsRegistry {
    let mut sources: Vec<SettingsSource> = SETTINGS_SOURCES.to_vec();
    sources.push(SettingsSource { krate: "fid-capture", settings: capture_settings });
    settings(&sources, &workspace_catalogue().unwrap()).unwrap()
}

fn with_ctx<T>(
    install: &Install,
    registry: &SettingsRegistry,
    caller: Caller,
    f: impl FnOnce(&SettingsCtx<'_>) -> T,
) -> T {
    let journal = RecJournal::default();
    let log = Log::default();
    let ctx = SettingsCtx {
        registry,
        caller,
        project: None,
        user: &install.user,
        machine: &install.machine,
        journal: &journal,
        log: &log,
    };
    f(&ctx)
}

fn instant(s: &str) -> UtcInstant {
    UtcInstant::parse(s).unwrap_or_else(|| panic!("{s} parses"))
}

fn retain_text(p: &RecordingPolicy) -> String {
    match p.retain_until(instant(START)) {
        Ok(None) => "none".to_string(),
        Ok(Some(t)) => t.to_string(),
        Err(RetentionError::Unknown) => "unknown".to_string(),
        Err(e) => panic!("unexpected {e}"),
    }
}

/// The stored JSON text of one key state of the matrix; `None` stores nothing.
fn stored(key: &str, state: &str) -> Option<String> {
    match state {
        "default" => None,
        "invalid" if key == RETENTION_DAYS_KEY => Some("36501".to_string()),
        "invalid" => Some("\"maybe\"".to_string()),
        v if key == RETENTION_DAYS_KEY => Some(v.to_string()),
        v => Some(format!("\"{v}\"")),
    }
}

// ------------------------------------------------------------------ declarations (REQ-001)

#[test]
fn declarations_are_admin_machine_only_with_the_spec_defaults() {
    let registry = SettingsRegistry::build(&capture_settings()).unwrap();
    let keys: Vec<&str> = registry.iter().map(|d| d.key()).collect();
    assert_eq!(keys, POLICY_KEYS);
    let defaults = [
        (RECORDING_KEY, "\"allowed\""),
        (RETENTION_DAYS_KEY, "0"),
        (SCREENSHOTS_KEY, "\"allowed\""),
        (WINDOW_CAPTURE_KEY, "\"allowed\""),
    ];
    for (key, default) in defaults {
        let d = registry.get(key).unwrap();
        assert!(d.admin(), "{key} is admin-flagged");
        assert_eq!(d.scopes().collect::<Vec<_>>(), [Scope::Machine], "{key} allows machine scope only");
        assert_eq!(d.owner(), "capture");
        assert_eq!(to_canonical_bytes(d.default_value()).unwrap(), default.as_bytes(), "{key} default");
    }
}

#[test]
fn capture_keys_build_with_every_workspace_setting() {
    let registry = workspace_registry();
    for key in POLICY_KEYS {
        assert!(registry.get(key).is_some(), "{key}");
    }
}

// ------------------------------------------------------------------ AC-1

struct Row {
    states: [String; 4],
    kind: MediaKind,
    decision: String,
    mandated: bool,
    retain_until: String,
}

fn matrix() -> Vec<Row> {
    let text = std::fs::read_to_string(Path::new(FIXTURES).join("policy-matrix.csv")).unwrap();
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    assert_eq!(
        lines.next(),
        Some("recording,window_capture,screenshots,retention_days,kind,decision,mandated,retain_until")
    );
    lines
        .map(|l| {
            let f: Vec<&str> = l.split(',').collect();
            assert_eq!(f.len(), 8, "{l}");
            Row {
                states: [f[0].to_string(), f[1].to_string(), f[2].to_string(), f[3].to_string()],
                kind: MediaKind::parse(f[4]).unwrap_or_else(|| panic!("kind {}", f[4])),
                decision: f[5].to_string(),
                mandated: match f[6] {
                    "true" => true,
                    "false" => false,
                    m => panic!("mandated {m}"),
                },
                retain_until: f[7].to_string(),
            }
        })
        .collect()
}

#[test]
fn ac1_policy_matrix() {
    let rows = matrix();
    assert_eq!(rows.len(), 1600);
    let mut combos: BTreeMap<[String; 4], Vec<&Row>> = BTreeMap::new();
    for r in &rows {
        combos.entry(r.states.clone()).or_default().push(r);
    }
    assert_eq!(combos.len(), 400);
    let install = Install::new("ac1");
    let keys = [RECORDING_KEY, WINDOW_CAPTURE_KEY, SCREENSHOTS_KEY, RETENTION_DAYS_KEY];
    for (states, rows) in combos {
        let values: Vec<String> =
            keys.iter().zip(&states).filter_map(|(k, s)| stored(k, s).map(|v| format!("\"{k}\": {v}"))).collect();
        install.write(Scope::Machine, &values.join(", "));
        let (policy, warnings) = install.policy();
        let invalid = states.iter().filter(|s| *s == "invalid").count();
        assert_eq!(warnings.len(), invalid, "{states:?}: one warning per invalid value");
        assert_eq!(rows.len(), 4, "{states:?}");
        for r in rows {
            let got = policy.check(r.kind);
            assert_eq!(got.to_string(), r.decision, "{states:?} {}", r.kind);
            assert_eq!(got.is_allowed(), r.decision == "allow");
            assert_eq!(policy.current().mandated(), r.mandated, "{states:?}");
            assert_eq!(retain_text(&policy), r.retain_until, "{states:?}");
        }
    }
}

// ------------------------------------------------------------------ AC-2

#[test]
fn ac2_fresh_install_lists_the_defaults() {
    let install = Install::new("ac2");
    let registry = workspace_registry();
    let params = ListValuesParams { prefix: Some("capture".to_string()), scope: None };
    let rows = with_ctx(&install, &registry, HUMAN_CLI, |ctx| list_values(ctx, params).unwrap());
    let got = to_canonical_bytes(&list_to_value(&rows)).unwrap();
    let want = std::fs::read(Path::new(FIXTURES).join("list-values-fresh.json")).unwrap();
    let want = to_canonical_bytes(&parse(want.strip_suffix(b"\n").unwrap()).unwrap()).unwrap();
    assert_eq!(String::from_utf8(got).unwrap(), String::from_utf8(want).unwrap());
    let (policy, warnings) = install.policy();
    assert!(warnings.is_empty());
    for kind in MediaKind::ALL {
        assert_eq!(policy.check(kind), Decision::Allow, "{kind}");
    }
    assert!(!policy.current().mandated(), "a fresh install records nothing by default");
}

// ------------------------------------------------------------------ AC-3

#[test]
fn ac3_set_value_refuses_the_policy_keys_and_changes_nothing() {
    let install = Install::new("ac3");
    let registry = workspace_registry();
    let before = install.policy();
    for key in POLICY_KEYS {
        let value = if key == RETENTION_DAYS_KEY { CValue::U64(30) } else { CValue::Str("forbidden".into()) };
        for scope in [Scope::Machine, Scope::User] {
            for caller in [HUMAN_CLI, AGENT_MCP] {
                let p = SetValueParams { key: key.to_string(), scope, value: SettingValue(value.clone()) };
                let journal = RecJournal::default();
                let log = Log::default();
                let ctx = SettingsCtx {
                    registry: &registry,
                    caller,
                    project: None,
                    user: &install.user,
                    machine: &install.machine,
                    journal: &journal,
                    log: &log,
                };
                let err = set_value(&ctx, p).unwrap_err();
                assert_eq!(err.code(), "admin_setting", "{key} {scope} {caller:?}");
                assert!(journal.0.borrow().is_empty(), "nothing journaled");
            }
        }
    }
    assert!(!install.machine_path().exists(), "the machine file was not written");
    assert!(!install.user.path().exists(), "the user file was not written");
    assert_eq!(install.policy(), before, "the policy is unchanged");
}

#[test]
fn only_the_admin_command_by_a_human_changes_the_policy() {
    let install = Install::new("admin");
    let registry = workspace_registry();
    let forbid = |caller| {
        let p = SetValueParams {
            key: RECORDING_KEY.to_string(),
            scope: Scope::Machine,
            value: SettingValue(CValue::Str("forbidden".into())),
        };
        with_ctx(&install, &registry, caller, |ctx| set_admin_value(ctx, p))
    };
    assert_eq!(forbid(AGENT_MCP).unwrap_err().code(), "policy");
    assert_eq!(install.policy().0.check(MediaKind::ViewTrack), Decision::Allow);
    forbid(HUMAN_CLI).unwrap();
    let (policy, warnings) = install.policy();
    assert!(warnings.is_empty());
    let refused = Decision::Forbid { key: RECORDING_KEY, cause: ForbidCause::Forbidden };
    assert_eq!(policy.check(MediaKind::ViewTrack), refused);
    assert_eq!(policy.check(MediaKind::ViewportVideo), refused);
    assert_eq!(policy.check(MediaKind::WindowVideo), refused);
    assert_eq!(policy.check(MediaKind::Screenshot), Decision::Allow);
}

// ------------------------------------------------------------------ AC-4

#[test]
fn ac4_retain_until() {
    let install = Install::new("ac4");
    install.write(Scope::Machine, r#""capture.retention_days": 30"#);
    let (policy, _) = install.policy();
    assert_eq!(policy.retain_until(instant(START)), Ok(Some(instant("2026-12-17T10:00:00Z"))));
    assert_eq!(policy.retain_until(instant(START)).unwrap().unwrap().to_string(), "2026-12-17T10:00:00Z");
    install.write(Scope::Machine, r#""capture.retention_days": 0"#);
    assert_eq!(install.policy().0.retain_until(instant(START)), Ok(None));
    install.write(Scope::Machine, "");
    assert_eq!(install.policy().0.retain_until(instant(START)), Ok(None), "default 0 keeps");
}

#[test]
fn retain_until_edges() {
    let p = |days| RecordingPolicy::from_policy(Policy { retention_days: Some(days), ..Policy::default() });
    // Across a leap day and the full range of the key (hand-computed).
    assert_eq!(p(1).retain_until(instant("2028-02-28T23:59:59Z")), Ok(Some(instant("2028-02-29T23:59:59Z"))));
    assert_eq!(p(36_500).retain_until(instant("2000-01-01T00:00:00Z")), Ok(Some(instant("2099-12-07T00:00:00Z"))));
    assert_eq!(p(1).retain_until(instant("9999-12-31T00:00:00Z")), Err(RetentionError::OutOfRange));
    assert_eq!(p(1).retain_until(instant("9999-12-30T23:59:59Z")), Ok(Some(UtcInstant::MAX)));
    assert_eq!(RecordingPolicy::default().retain_until(instant(START)), Err(RetentionError::Unknown));
}

#[test]
fn utc_instants_parse_and_print_exactly() {
    for s in ["1970-01-01T00:00:00Z", "0001-01-01T00:00:00Z", "9999-12-31T23:59:59Z", "2000-02-29T12:34:56Z", START] {
        assert_eq!(instant(s).to_string(), s);
    }
    assert_eq!(instant("1970-01-01T00:00:00Z").unix_seconds(), 0);
    assert_eq!(instant(START).unix_seconds(), 1_794_909_600);
    assert_eq!(instant("0001-01-01T00:00:00Z"), UtcInstant::MIN);
    assert_eq!(instant("9999-12-31T23:59:59Z"), UtcInstant::MAX);
    for bad in [
        "2026-11-17T10:00:00",
        "2026-11-17T10:00:00+00:00",
        "2026-11-17 10:00:00Z",
        "2026-11-17T10:00:00.5Z",
        "2026-02-29T00:00:00Z",
        "1900-02-29T00:00:00Z",
        "2026-13-01T00:00:00Z",
        "2026-04-31T00:00:00Z",
        "2026-11-17T24:00:00Z",
        "2026-11-17T10:60:00Z",
        "2026-11-17T10:00:60Z",
        "0000-01-01T00:00:00Z",
        "+026-11-17T10:00:00Z",
        "2026-1a-17T10:00:00Z",
        "",
    ] {
        assert_eq!(UtcInstant::parse(bad), None, "{bad:?}");
    }
    assert_eq!(UtcInstant::from_unix_seconds(UtcInstant::MAX.unix_seconds() + 1), None);
    assert_eq!(UtcInstant::from_unix_seconds(UtcInstant::MIN.unix_seconds() - 1), None);
}

// ------------------------------------------------------------------ fail closed

fn all_refused(policy: &RecordingPolicy, cause: ForbidCause) {
    for kind in MediaKind::ALL {
        match policy.check(kind) {
            Decision::Forbid { cause: c, .. } => assert_eq!(c, cause, "{kind}"),
            Decision::Allow => panic!("{kind} allowed"),
        }
    }
}

#[test]
fn an_absent_policy_refuses_everything() {
    let empty = RecordingPolicy::from_snapshot(&[], &[]);
    assert_eq!(empty, RecordingPolicy::default());
    assert_eq!(empty.current(), Policy::default());
    all_refused(&empty, ForbidCause::Unknown);
    assert!(!empty.current().mandated());
    // Each key alone is required by the media that depend on it.
    let install = Install::new("absent");
    let registry = SettingsRegistry::build(&capture_settings()).unwrap();
    let (full, _) = resolve(&registry, &install.sources(), |_| true);
    for key in POLICY_KEYS {
        let without: Vec<Resolved> = full.iter().filter(|r| r.key != key).cloned().collect();
        let p = RecordingPolicy::from_snapshot(&without, &[]);
        let refused: Vec<MediaKind> = MediaKind::ALL.into_iter().filter(|k| !p.check(*k).is_allowed()).collect();
        let want: &[MediaKind] = match key {
            k if k == SCREENSHOTS_KEY => &[MediaKind::Screenshot],
            k if k == WINDOW_CAPTURE_KEY => &[MediaKind::WindowVideo],
            _ => &[MediaKind::ViewTrack, MediaKind::ViewportVideo, MediaKind::WindowVideo],
        };
        assert_eq!(refused, want, "without {key}");
    }
}

#[test]
fn an_unreadable_machine_file_refuses_everything() {
    let install = Install::new("unreadable");
    install.write(Scope::Machine, r#""capture.recording": "mandated""#);
    assert!(install.policy().0.current().mandated());
    for bytes in [&b"not json"[..], br#"{"format": "fid-settings/2", "values": {}}"#, br#"{"a": 1, "a": 2}"#] {
        install.write_raw(Scope::Machine, bytes);
        let (policy, warnings) = install.policy();
        assert!(warnings.iter().any(|w| w.scope == Scope::Machine && w.reason == WarningReason::Unreadable));
        all_refused(&policy, ForbidCause::Unknown);
        assert!(!policy.current().mandated(), "an unreadable mandate records nothing");
        assert_eq!(policy.current(), Policy::default());
    }
}

#[test]
fn user_scope_values_never_change_the_policy() {
    let install = Install::new("user");
    install.write(Scope::Machine, r#""capture.recording": "mandated", "capture.window_capture": "forbidden""#);
    let (machine_only, _) = install.policy();
    for user in [
        r#""capture.recording": "allowed", "capture.window_capture": "allowed""#,
        r#""capture.recording": "maybe", "capture.retention_days": -1"#,
    ] {
        install.write(Scope::User, user);
        let (policy, warnings) = install.policy();
        assert!(!warnings.is_empty());
        assert!(warnings.iter().all(|w| w.scope == Scope::User), "{warnings:?}");
        assert_eq!(policy, machine_only, "{user}");
    }
    install.write_raw(Scope::User, b"not json");
    assert_eq!(install.policy().0, machine_only);
    assert!(machine_only.current().mandated());
    assert_eq!(
        machine_only.check(MediaKind::WindowVideo),
        Decision::Forbid { key: WINDOW_CAPTURE_KEY, cause: ForbidCause::Forbidden }
    );
}

#[test]
fn snapshots_from_another_scope_or_duplicated_are_unknown() {
    let r = |key: &str, v: &str, source| Resolved { key: key.to_string(), value: parse(v.as_bytes()).unwrap(), source };
    let good = vec![
        r(RECORDING_KEY, "\"allowed\"", Source::Machine),
        r(RETENTION_DAYS_KEY, "7", Source::Default),
        r(SCREENSHOTS_KEY, "\"allowed\"", Source::Machine),
        r(WINDOW_CAPTURE_KEY, "\"allowed\"", Source::Default),
    ];
    let p = RecordingPolicy::from_snapshot(&good, &[]);
    assert_eq!(
        p.current(),
        Policy {
            recording: Some(Recording::Allowed),
            window_capture: Some(Permission::Allowed),
            screenshots: Some(Permission::Allowed),
            retention_days: Some(7),
        }
    );
    // A value from user or project scope cannot come from a machine-only declaration.
    for source in [Source::User, Source::Project] {
        let mut bad = good.clone();
        bad[0].source = source;
        assert_eq!(RecordingPolicy::from_snapshot(&bad, &[]).current().recording, None, "{source:?}");
    }
    // The same key twice is ambiguous.
    let mut twice = good.clone();
    twice.push(r(RECORDING_KEY, "\"forbidden\"", Source::Machine));
    assert_eq!(RecordingPolicy::from_snapshot(&twice, &[]).current().recording, None);
    // Values outside the key's values.
    for (key, v) in [
        (RECORDING_KEY, "\"Allowed\""),
        (RECORDING_KEY, "true"),
        (SCREENSHOTS_KEY, "\"mandated\""),
        (WINDOW_CAPTURE_KEY, "null"),
        (RETENTION_DAYS_KEY, "36501"),
        (RETENTION_DAYS_KEY, "-1"),
        (RETENTION_DAYS_KEY, "1.5"),
        (RETENTION_DAYS_KEY, "\"30\""),
    ] {
        let snap: Vec<Resolved> =
            good.iter().map(|g| if g.key == key { r(key, v, Source::Machine) } else { g.clone() }).collect();
        let cur = RecordingPolicy::from_snapshot(&snap, &[]).current();
        let unknown = match key {
            k if k == RECORDING_KEY => cur.recording.is_none(),
            k if k == SCREENSHOTS_KEY => cur.screenshots.is_none(),
            k if k == WINDOW_CAPTURE_KEY => cur.window_capture.is_none(),
            _ => cur.retention_days.is_none(),
        };
        assert!(unknown, "{key} = {v}");
    }
    // A machine-scope warning for a key makes it unknown, even if a value was resolved.
    let w = SettingWarning {
        key: Some(RECORDING_KEY.to_string()),
        scope: Scope::Machine,
        reason: WarningReason::InvalidValue,
    };
    assert_eq!(RecordingPolicy::from_snapshot(&good, &[w]).current().recording, None);
}

// ------------------------------------------------------------------ REQ-005

#[test]
fn evaluation_is_read_only_and_repeatable() {
    let install = Install::new("pure");
    install.write(Scope::Machine, r#""capture.recording": "mandated", "capture.retention_days": 30"#);
    let before = std::fs::read(install.machine_path()).unwrap();
    let (a, wa) = install.policy();
    let (b, wb) = install.policy();
    assert_eq!((a, wa), (b, wb));
    for kind in MediaKind::ALL {
        assert_eq!(a.check(kind), a.check(kind));
        assert_eq!(a.check(kind), b.check(kind));
    }
    assert_eq!(a.retain_until(instant(START)), b.retain_until(instant(START)));
    assert_eq!(std::fs::read(install.machine_path()).unwrap(), before, "reading changes nothing");
    assert!(!install.user.path().exists());
}

#[test]
fn media_kind_wire_strings() {
    for k in MediaKind::ALL {
        assert_eq!(MediaKind::parse(k.as_str()), Some(k));
        assert_eq!(k.is_recording(), k != MediaKind::Screenshot);
    }
    assert_eq!(MediaKind::parse("Screenshot"), None);
    for r in [Recording::Allowed, Recording::Forbidden, Recording::Mandated] {
        assert_eq!(Recording::parse(r.as_str()), Some(r));
    }
    for p in [Permission::Allowed, Permission::Forbidden] {
        assert_eq!(Permission::parse(p.as_str()), Some(p));
    }
}
